package com.imageresizer.usage;

import jakarta.persistence.*;
import lombok.*;

import java.time.Instant;

/**
 * One row per AI tool call. Used to count and enforce daily limits.
 *
 * <p>DDL (generated by Hibernate ddl-auto=update):
 * <pre>
 * CREATE TABLE usage_logs (
 *   id         BIGINT AUTO_INCREMENT PRIMARY KEY,
 *   user_id    BIGINT       NULL,        -- NULL for anonymous callers
 *   ip_address VARCHAR(45)  NOT NULL,
 *   tool       VARCHAR(50)  NOT NULL,    -- remove_bg | upscale | smart_crop
 *   used_at    DATETIME(6)  NOT NULL
 * );
 * </pre>
 */
@Entity
@Table(name = "usage_logs",
        indexes = {
                @Index(name = "idx_usage_user_date",  columnList = "user_id, used_at"),
                @Index(name = "idx_usage_ip_date",    columnList = "ip_address, used_at")
        })
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class UsageLog {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** Null for anonymous (IP-only) callers. */
    @Column(name = "user_id")
    private Long userId;

    @Column(name = "ip_address", nullable = false, length = 45)
    private String ipAddress;

    /** Which AI tool was invoked: remove_bg | upscale | smart_crop. */
    @Column(nullable = false, length = 50)
    private String tool;

    @Column(name = "used_at", nullable = false, updatable = false)
    private Instant usedAt;

    @PrePersist
    void prePersist() {
        usedAt = Instant.now();
    }
}
